pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, type(uint128).max);

        vm.deal(address(c), depositAmount);

        address owner = address(0x1234);
        vm.prank(owner);
        c = new SimpleWallet();
        vm.deal(address(c), depositAmount);

        address(c).call{value: 0}("");

        uint256 balanceBefore = address(c).balance;

        vm.prank(owner);
        c.withdrawAll();

        assertTrue(address(c).balance == 0);
    }
}
